  MAPS = {
    0 => {
      'GARDEVOIR: ...And she\'s gone.' => ['GARDEVOIR: ...Und sie ist weg.', 'GUARDEVOIR: ...Und sie ist weg.'],
      'GARDEVOIR: The barrier-- that\'s right!' => ['GARDEVOIR: Die Barriere – stimmt ja!', 'GUARDEVOIR: Die Barriere – stimmt ja!'],
      'GARDEVOIR: With these mysterious machines amping up their Pokémon\'s powers, there\'s no telling what they\'ll do next!' => ['GARDEVOIR: Mit diesen mysteriösen Maschinen, die die Kräfte ihrer Pokémon verstärken, ist völlig unklar, was sie als Nächstes anstellen werden!', 'GUARDEVOIR: Mit diesen mysteriösen Maschinen, die die Kräfte ihrer Pokémon verstärken, ist völlig unklar, was sie als Nächstes anstellen werden!'],
      'GARDEVOIR: ...Yes, right.' => ['GARDEVOIR: ... Ja, richtig.', 'GUARDEVOIR: ... Ja, richtig.'],
      'GARDEVOIR: Oh? Does that mean you don\'t enjoy the work?' => ['GARDEVOIR: Oh? Bedeutet das, dass Ihnen die Arbeit keinen Spaß macht?', 'GUARDEVOIR: Oh? Bedeutet das, dass Ihnen die Arbeit keinen Spaß macht?'],
      'GARDEVOIR: How boring!' => ['GARDEVOIR: Wie langweilig!', 'GUARDEVOIR: Wie langweilig!'],
      'GARDEVOIR: Oh my, this is juicy!' => ['GARDEVOIR: Oh wow, das wird ja richtig juicy!', 'GUARDEVOIR: Oh wow, das wird ja richtig juicy!'],
      'GARDEVOIR: Lovely! Do tell, what happened?' => ['GARDEVOIR: Schön! Erzählen Sie, was passiert ist?', 'GUARDEVOIR: Schön! Erzählen Sie, was passiert ist?'],
      'GARDEVOIR: What? I say when the interview ends, not you!' => ['GARDEVOIR: Was? Ich sage, wenn das Interview endet, nicht Sie!', 'GUARDEVOIR: Was? Ich sage, wenn das Interview endet, nicht Sie!'],
      'GARDEVOIR: What\'s the matter? You seem almost disappointed!' => ['GARDEVOIR: Was ist los? Du scheinst fast enttäuscht zu sein!', 'GUARDEVOIR: Was ist los? Du scheinst fast enttäuscht zu sein!'],
      'GARDEVOIR: That\'s right, you gave up your career for your son before. Do you regret doing that?' => ['GARDEVOIR: Stimmt, Sie haben schon einmal Ihre Karriere für Ihren Sohn aufgegeben. Bedauern Sie es, das getan zu haben?', 'GUARDEVOIR: Stimmt, Sie haben schon einmal Ihre Karriere für Ihren Sohn aufgegeben. Bedauern Sie es, das getan zu haben?'],
      'GARDEVOIR: You mean your son, of course. How touching!' => ['GARDEVOIR: Du meinst natürlich deinen Sohn. Wie rührend!', 'GUARDEVOIR: Du meinst natürlich deinen Sohn. Wie rührend!'],
      'GARDEVOIR: In his recent exploits, it seems likely he\'s been working under and assisting Team Meteor in destroying the region!' => ['GARDEVOIR: Bei seinen jüngsten Aktionen scheint es wahrscheinlich, dass er unter Team Meteor gearbeitet und dabei geholfen hat, die Region zu zerstören!', 'GUARDEVOIR: Bei seinen jüngsten Aktionen scheint es wahrscheinlich, dass er unter Team Meteor gearbeitet und dabei geholfen hat, die Region zu zerstören!'],
      'GARDEVOIR: Ah, in time, but let\'s finish the interview first?' => ['GARDEVOIR: Ah, rechtzeitig, aber beenden wir zuerst das Interview?', 'GUARDEVOIR: Ah, rechtzeitig, aber beenden wir zuerst das Interview?'],
      'GARDEVOIR: ...Yes, missus.' => ['GARDEVOIR: ... Ja, Ma’am.', 'GUARDEVOIR: ... Ja, Ma’am.'],
      'GARDEVOIR: Just where were you looking?! You walked right into that table!' => ['GARDEVOIR: Wo genau hast du gesucht?! Du bist direkt an den Tisch gelaufen!', 'GUARDEVOIR: Wo genau hast du gesucht?! Du bist direkt an den Tisch gelaufen!'],
      'GARDEVOIR: Wait, were you wearing those shades just to hide the fact that your eyes were closed as you were walking?!' => ['GARDEVOIR: Moment, hast du diese Sonnenbrille nur getragen, um die Tatsache zu verbergen, dass deine Augen beim Gehen geschlossen waren?!', 'GUARDEVOIR: Moment, hast du diese Sonnenbrille nur getragen, um die Tatsache zu verbergen, dass deine Augen beim Gehen geschlossen waren?!'],
      'GARDEVOIR: I\'m not so sure that\'s quite how sleepwalking works, dear.' => ['GARDEVOIR: Ich bin mir nicht so sicher, ob Schlafwandeln so funktioniert, Liebes.', 'GUARDEVOIR: Ich bin mir nicht so sicher, ob Schlafwandeln so funktioniert, Liebes.'],
      'GARDEVOIR: As if I would!' => ['GARDEVOIR: Als ob ich es tun würde!', 'GUARDEVOIR: Als ob ich es tun würde!'],
      'GARDEVOIR: Could you tell us how that got started?' => ['GARDEVOIR: Können Sie uns erzählen, wie das angefangen hat?', 'GUARDEVOIR: Können Sie uns erzählen, wie das angefangen hat?'],
      'GARDEVOIR: I\'m... sure it is.' => ['GARDEVOIR: Ich bin... sicher, dass es so ist.', 'GUARDEVOIR: Ich bin... sicher, dass es so ist.'],
      'GARDEVOIR: NO.' => ['GARDEVOIR: NEIN.', 'GUARDEVOIR: NEIN.'],
      'GARDEVOIR: Uh.' => ['GARDEVOIR: Äh.', 'GUARDEVOIR: Äh.'],
      'GARDEVOIR: That\'s-- No, wait, that\'s my job.' => ['GARDEVOIR: Das ist... Nein, warte, das ist mein Job.', 'GUARDEVOIR: Das ist... Nein, warte, das ist mein Job.'],
      'GARDEVOIR: Oh! Well, no need to be embarrassed, darling.' => ['GARDEVOIR: Oh! Nun ja, es besteht kein Grund, sich zu schämen, Liebling.', 'GUARDEVOIR: Oh! Nun ja, es besteht kein Grund, sich zu schämen, Liebling.'],
      'GARDEVOIR: Well-- okay.' => ['GARDEVOIR: Nun ja, okay.', 'GUARDEVOIR: Nun ja, okay.'],
      'GARDEVOIR: Of course! That\'s just what a good hostess should-- Wait, what do you mean, "Once in a while"?' => ['GARDEVOIR: Natürlich! Das ist genau das, was eine gute Gastgeberin tun sollte – Moment, was meinst du mit „Ab und zu“?', 'GUARDEVOIR: Natürlich! Das ist genau das, was eine gute Gastgeberin tun sollte – Moment, was meinst du mit „Ab und zu“?'],
      'GARDEVOIR: Of course you\'re wrong!' => ['GARDEVOIR: Natürlich liegen Sie falsch!', 'GUARDEVOIR: Natürlich liegen Sie falsch!'],
      'GARDEVOIR: She called the police!' => ['GARDEVOIR: Sie hat die Polizei gerufen!', 'GUARDEVOIR: Sie hat die Polizei gerufen!'],
      'GARDEVOIR: And still not half as rude as you\'re being right now!' => ['GARDEVOIR: Und immer noch nicht halb so unhöflich, wie Sie sich gerade verhalten!', 'GUARDEVOIR: Und immer noch nicht halb so unhöflich, wie Sie sich gerade verhalten!'],
      'GARDEVOIR: That\'s not what I\'m saying! Ugh!' => ['GARDEVOIR: Das meine ich nicht! Pfui!', 'GUARDEVOIR: Das meine ich nicht! Pfui!'],
      'GARDEVOIR: That\'s none of your business!' => ['GARDEVOIR: Das geht dich nichts an!', 'GUARDEVOIR: Das geht dich nichts an!'],
      'GARDEVOIR: Lying?' => ['GARDEVOIR: Lügen?', 'GUARDEVOIR: Lügen?'],
      'GARDEVOIR: A character? Like in a game or something? That\'s ridiculous.' => ['GARDEVOIR: Eine Figur? Wie in einem Spiel oder so? Das ist lächerlich.', 'GUARDEVOIR: Eine Figur? Wie in einem Spiel oder so? Das ist lächerlich.'],
      'GARDEVOIR: That\'s nonsense...' => ['GARDEVOIR: Das ist Unsinn...', 'GUARDEVOIR: Das ist Unsinn...'],
      'GARDEVOIR: Those are some mighty words for such a tiny person!' => ['GARDEVOIR: Große Worte für so eine kleine Person!', 'GUARDEVOIR: Große Worte für so eine kleine Person!'],
      'GARDEVOIR: Your friends? Whoever could you mean?' => ['GARDEVOIR: Deine Freunde? Wen könntest du meinen?', 'GUARDEVOIR: Deine Freunde? Wen könntest du meinen?'],
      'GARDEVOIR: Admirable words from someone who\'s been through so much!' => ['GARDEVOIR: Bewundernswerte Worte von jemandem, der so viel durchgemacht hat!', 'GUARDEVOIR: Bewundernswerte Worte von jemandem, der so viel durchgemacht hat!'],
      'GARDEVOIR: The princess of the wind? However do you mean?' => ['GARDEVOIR: Die Prinzessin des Windes? Aber meinst du?', 'GUARDEVOIR: Die Prinzessin des Windes? Aber meinst du?'],
      'GARDEVOIR: Oh my, even stronger? That\'s quite a claim!' => ['GARDEVOIR: Oh mein Gott, noch stärker? Das ist eine ziemliche Behauptung!', 'GUARDEVOIR: Oh mein Gott, noch stärker? Das ist eine ziemliche Behauptung!'],
      'Everyone\'s always like "Whaaat? Why would a little girl want a Pokémon like that?"' => ['Jeder sagt immer: „Was? Warum sollte ein kleines Mädchen so einen Pokémon wollen? “', 'Jeder sagt immer: „Waaas? Warum sollte ein kleines Mädchen so ein Pokémon wollen?“'],
      'GARDEVOIR: That\'s quite the fighting spirit!' => ['GARDEVOIR: Das ist genau der Kampf-Geist!', 'GUARDEVOIR: Das ist genau der Kampf-Geist!'],
      'Still, now you know-- Teknite Ridge is a place worth visiting at night if you want a Pokémon like this!' => ['Jetzt wissen Sie jedoch: Teknite Ridge ist ein Ort, der einen Besuch bei Nacht wert ist, wenn Sie einen Pokémon wie diesen wollen!', 'Jetzt wissen Sie es: Teknite Ridge ist nachts einen Besuch wert, wenn Sie so ein Pokémon wollen!'],
    },
