    ['Valeria', 'OrderlyF', 'introSpeech', 'I\'m done holding back!'] => 'Ich halte mich nicht länger zurück!',
    ['Valeria', 'OrderlyF', 'winSpeech', 'My power ascends!'] => 'Meine Macht steigt!',
    ['Valeria', 'OrderlyF', 'loseSpeech', 'You crossed a line!'] => 'Du bist zu weit gegangen!',
    ['Delaney', 'OrderlyF', 'introSpeech', 'I\'m not sure this was the right part-time job for me...'] => 'Ich bin mir nicht sicher, ob das der richtige Nebenjob für mich ist...',
    ['Delaney', 'OrderlyF', 'winSpeech', 'The bonus pay\'s great though!'] => 'Der Bonus ist allerdings klasse!',
    ['Delaney', 'OrderlyF', 'loseSpeech', 'Nope. Definitely should\'ve applied at Sweet Kiss Candy Shop.'] => 'Nein. Ich hätte mich doch beim Sweet Kiss Candy Shop bewerben sollen.',
