    ['Roberto', 'MAGMA1', 'introSpeech', 'You want to know why I joined the Magma Gang?'] => 'Willst du wissen, warum ich der Magma-Gang beigetreten bin?',
    ['Roberto', 'MAGMA1', 'winSpeech', 'It\'s because we\'re the strongest in Reborn City!'] => 'Weil wir die Stärksten in Reborn City sind!',
    ['Roberto', 'MAGMA1', 'loseSpeech', 'It\'s because I just can\'t stand the cold. '] => 'Weil ich die Kälte einfach nicht ausstehen kann. ',
    ['Damian', 'MAGMA1', 'introSpeech', 'Brace yourself for a Heat Wave!'] => 'Mach dich auf eine Hitzewelle gefasst!',
    ['Damian', 'MAGMA1', 'winSpeech', 'You Overheated!'] => 'Du bist völlig überhitzt!',
    ['Damian', 'MAGMA1', 'loseSpeech', 'I\'m Fire Blasting off again...'] => 'Ich mach mich aus dem Staub...',
    ['Fiwam', 'MAGMA1', 'introSpeech', 'I keep telling the boss we need new uniforms...'] => 'Ich sag dem Boss ständig, dass wir neue Uniformen brauchen...',
    ['Fiwam', 'MAGMA1', 'winSpeech', 'Maybe he\'ll listen now!'] => 'Vielleicht hört er jetzt auf mich!',
    ['Fiwam', 'MAGMA1', 'loseSpeech', 'Honestly, why can\'t we look more stylish?'] => 'Ehrlich, warum können wir nicht stylischer aussehen?',
    ['Graham', 'MAGMA1', 'introSpeech', 'Don\'t take this personally.'] => 'Nimm\'s nicht persönlich.',
    ['Graham', 'MAGMA1', 'winSpeech', 'It was just business.'] => 'War nur Geschäft.',
    ['Graham', 'MAGMA1', 'loseSpeech', 'Okay, I get it!'] => 'Okay, ich hab\'s kapiert!',
    ['Tylor', 'Cultist', 'introSpeech', 'Normally, I wouldn\'t do this, but...'] => 'Normalerweise würde ich das nicht tun, aber...',
    ['Tylor', 'Cultist', 'winSpeech', 'I\'m fairy certain I just beat you!'] => 'Ich bin mir feenomenal sicher, dass ich dich gerade besiegt habe!',
    ['Tylor', 'Cultist', 'loseSpeech', 'Stop \'dragon my heart around!'] => 'Hör auf, mein Herz durch den Drachen zu ziehen!',
    ['Jaren', 'BATTLEGIRL', 'introSpeech', 'I\'ll show you my fighting spirit!'] => 'Ich zeig dir meinen Kampfgeist!',
    ['Jaren', 'BATTLEGIRL', 'winSpeech', 'Was that enough spirit for you?'] => 'War das genug Kampfgeist für dich?',
    ['Jaren', 'BATTLEGIRL', 'loseSpeech', 'Your Pokemon were distracting, okay? They\'re too cute!'] => 'Deine Pokémon haben mich abgelenkt, okay? Die sind zu süß!',
    ['Cordell', 'TechNerd', 'introSpeech', 'This is my 17th match this week. '] => 'Das ist mein 17. Match diese Woche. ',
