    ['Cordell', 'TechNerd', 'loseSpeech', 'Match 17: loss. '] => 'Match 17: verloren. ',
    ['Ro', 'Doxy', 'introSpeech', 'Check out my new shoes!'] => 'Schau dir meine neuen Schuhe an!',
