    ['Ro', 'Doxy', 'loseSpeech', 'I\'m just too excited about these shoes!'] => 'Ich freu mich einfach zu sehr über diese Schuhe!',
    ['Marshall', 'YOUNGSTER', 'introSpeech', 'I have my own place now! Yay!'] => 'Ich hab jetzt mein eigenes Zuhause! Yay!',
    ['Marshall', 'YOUNGSTER', 'winSpeech', 'I accept this win in the name of Fort Marshall!'] => 'Diesen Sieg widme ich Fort Marshall!',
    ['Marshall', 'YOUNGSTER', 'loseSpeech', 'It\'s really a tree fort...'] => 'Ist eigentlich nur ein Baumhaus...',
    ['Johan', 'YOUNGSTER', 'introSpeech', 'Do you like Fossil Pokemon?'] => 'Magst du Fossil-Pokémon?',
    ['Johan', 'YOUNGSTER', 'winSpeech', 'Next time, you should battle with Fossil Pokemon!'] => 'Nächstes Mal solltest du mit Fossil-Pokémon kämpfen!',
    ['Johan', 'YOUNGSTER', 'loseSpeech', 'Fossil Pokemon are the best! My favorite\'s Carracosta!'] => 'Fossil-Pokémon sind die Besten! Mein Liebling ist Karippas!',
    ['Shea', 'COOLTRAINER_Female', 'introSpeech', 'I am beauty! I am grace!'] => 'Ich bin Schönheit! Ich bin Anmut!',
    ['Shea', 'COOLTRAINER_Female', 'winSpeech', 'I stole victory in this place!'] => 'Hier hab ich den Sieg geklaut!',
    ['Shea', 'COOLTRAINER_Female', 'loseSpeech', 'Even in defeat, I\'m elegant!'] => 'Selbst in der Niederlage bin ich elegant!',
    ['Deneb', 'COOLTRAINER_Female', 'introSpeech', 'Ready? Okay!'] => 'Bereit? Okay!',
    ['Deneb', 'COOLTRAINER_Female', 'winSpeech', 'Here we go, no need to fear it! I\'m filled up with battling spirit!'] => 'Los geht\'s, keine Angst! Mein Kampfgeist ist voll entflammt!',
    ['Deneb', 'COOLTRAINER_Female', 'loseSpeech', 'That\'s all right, that\'s okay, I\'ll try again another day...'] => 'Schon okay, halb so wild, ich versuch\'s an einem anderen Tag...',
    ['Isiah', 'SWIMMERBOI', 'introSpeech', 'Hey, if you see my mom, don\'t tell her I was here, okay?'] => 'Hey, wenn du meine Mom siehst, sag ihr nicht, dass ich hier war, okay?',
    ['Isiah', 'SWIMMERBOI', 'winSpeech', 'Mom thinks I study all the time, but that\'s boring!'] => 'Mom denkt, ich lerne ständig, aber das ist langweilig!',
    ['Isiah', 'SWIMMERBOI', 'loseSpeech', 'I\'m supposed to be studying right now...'] => 'Ich sollte gerade lernen...',
    ['Garrett', 'SWIMMERBOI', 'introSpeech', 'Not much to say, huh?'] => 'Nicht viel zu sagen, was?',
    ['Garrett', 'SWIMMERBOI', 'winSpeech', 'You should try speaking up a bit more!'] => 'Du solltest ruhig etwas lauter sprechen!',
    ['Garrett', 'SWIMMERBOI', 'loseSpeech', 'It\'s okay. I don\'t always feel like talking either.'] => 'Schon gut. Manchmal hab ich auch keine Lust zu reden.',
