    ['Salma', 'LADY', 'loseSpeech', 'Huh? This wasn\'t the OKCufant meetup? Oh dear...'] => 'Hä? Das war gar nicht das OKCufant-Treffen? Oje...',
    ['Ansley', 'LADY', 'introSpeech', 'This is the best day of my life!'] => 'Das ist der beste Tag meines Lebens!',
    ['Ansley', 'LADY', 'winSpeech', 'First I get engaged, then I win against you- this day couldn\'t get any better!'] => 'Erst verlobe ich mich, dann gewinne ich gegen dich – besser kann der Tag nicht werden!',
    ['Ansley', 'LADY', 'loseSpeech', 'Even this can\'t dampen my spirits!'] => 'Nicht mal das kann mir die Laune verderben!',
    ['Holden', 'StreetRat', 'introSpeech', 'Heh heh...'] => 'Hehehe...',
    ['Holden', 'StreetRat', 'winSpeech', 'This place is sad, if even a kid like me can win!'] => 'Dieser Ort ist traurig, wenn sogar ein Kind wie ich gewinnen kann!',
    ['Holden', 'StreetRat', 'loseSpeech', 'I didn\'t know the trainers here were this strong!'] => 'Ich wusste gar nicht, dass die Trainer hier so stark sind!',
    ['Luca', 'StreetRat', 'introSpeech', 'What kind of riffraff did they let in here?'] => 'Was für ein Gesindel lassen die hier rein?',
    ['Luca', 'StreetRat', 'winSpeech', 'Take a closer look!'] => 'Sieh mal genauer hin!',
    ['Luca', 'StreetRat', 'loseSpeech', 'You beat me? I don\'t buy that!'] => 'Du hast mich besiegt? Das glaub ich nicht!',
    ['Jamison', 'HARDHAT', 'introSpeech', 'It\'s been a long shift. Time to cool down with a battle!'] => 'Die Schicht war lang. Zeit, mich mit einem Kampf abzukühlen!',
    ['Jamison', 'HARDHAT', 'winSpeech', 'Just what I needed!'] => 'Genau das hab ich gebraucht!',
    ['Jamison', 'HARDHAT', 'loseSpeech', 'Now I\'m even more stressed!'] => 'Jetzt bin ich noch gestresster!',
    ['Gunnar', 'HARDHAT', 'introSpeech', 'Behold the Great Gunnar, Reborn\'s most gorgeous gamer!'] => 'Bestaunt den großen Gunnar, Reborns schönsten Gamer!',
    ['Gunnar', 'HARDHAT', 'winSpeech', 'Gorgeous and godly in battle!'] => 'Schön und göttlich im Kampf!',
    ['Gunnar', 'HARDHAT', 'loseSpeech', 'Grumble grumble...'] => 'Grummel, grummel...',
    ['Pierce', 'SWIMMERBOI', 'introSpeech', 'This battle... Will it finally be enough for me?'] => 'Dieser Kampf... Reicht es diesmal endlich?',
    ['Pierce', 'SWIMMERBOI', 'winSpeech', 'Look at me now!'] => 'Sieh mich jetzt an!',
    ['Pierce', 'SWIMMERBOI', 'loseSpeech', 'I really tried to make it out!'] => 'Ich hab wirklich versucht, es hier rauszuschaffen!',
    ['Regina', 'SWIMMERGRIL', 'introSpeech', 'I came here with my friends! It\'s been a blast so far!'] => 'Ich bin mit meinen Freunden hier! Bis jetzt macht\'s riesigen Spaß!',
    ['Regina', 'SWIMMERGRIL', 'winSpeech', 'This battle was totally fun, too!'] => 'Der Kampf hat auch total Spaß gemacht!',
    ['Regina', 'SWIMMERGRIL', 'loseSpeech', 'You\'re so mean!!'] => 'Du bist so gemein!!',
    ['Cat', 'SWIMMERGRIL', 'introSpeech', 'It\'s so cold! Does someone have the air conditioner cranked up?'] => 'Es ist so kalt! Hat jemand die Klimaanlage voll aufgedreht?',
    ['Cat', 'SWIMMERGRIL', 'winSpeech', 'Aah, that\'s better. The battle warmed me up!'] => 'Aah, schon besser. Der Kampf hat mich aufgewärmt!',
    ['Cat', 'SWIMMERGRIL', 'loseSpeech', 'Seriously, why\'s it so icy in here?'] => 'Echt jetzt, warum ist es hier so eisig?',
    ['Sol', 'StreetRat', 'introSpeech', 'Man, it\'s nice out today.'] => 'Mann, heute ist\'s schön draußen.',
