    ['Gage', 'Casanova', 'loseSpeech', 'You\'re making my heart soar!'] => 'Du lässt mein Herz höherschlagen!',
    ['Ksldr', 'Casanova', 'introSpeech', 'I had a strange dream last night...'] => 'Letzte Nacht hatte ich einen seltsamen Traum...',
    ['Ksldr', 'Casanova', 'winSpeech', 'Y-you! Your scary face was in my dream!'] => 'D-du! Dein gruseliges Gesicht kam in meinem Traum vor!',
    ['Ksldr', 'Casanova', 'loseSpeech', 'A bittersweet dream, much like this battle.'] => 'Ein bittersüßer Traum, genau wie dieser Kampf.',
