    ['Jarrett', 'AQUA1', 'winSpeech', 'Heck yeah! My moves are awesome!'] => 'Oh ja! Meine Moves sind der Hammer!',
    ['Jarrett', 'AQUA1', 'loseSpeech', 'Okay, maybe I did get a little distracted.'] => 'Okay, vielleicht war ich doch ein bisschen abgelenkt.',
    ['Garett', 'AQUA1', 'introSpeech', 'Hey, kid. You taking care of this place?'] => 'Hey, Kleiner. Passt du hier auf?',
    ['Garett', 'AQUA1', 'winSpeech', 'Keep training. From what I hear, this place needs it.'] => 'Trainier weiter. Wie ich höre, kann dieser Ort das gebrauchen.',
    ['Garett', 'AQUA1', 'loseSpeech', 'Good, good.'] => 'Gut, gut.',
    ['Emanuel', 'HIKER', 'introSpeech', 'Sometimes you need a hard head to win!'] => 'Manchmal braucht man einen Dickschädel, um zu gewinnen!',
    ['Emanuel', 'HIKER', 'winSpeech', 'Strong and immovable as stone!'] => 'Stark und unbeweglich wie Stein!',
    ['Emanuel', 'HIKER', 'loseSpeech', 'I flinched!'] => 'Ich bin zurückgeschreckt!',
    ['Gustavo', 'HIKER', 'introSpeech', 'Charge! Charge!'] => 'Angriff! Angriff!',
    ['Gustavo', 'HIKER', 'winSpeech', 'Now that I win, can I get a Pokenav with a better battery?'] => 'Jetzt, wo ich gewonnen hab, krieg ich einen PokéNav mit besserem Akku?',
    ['Gustavo', 'HIKER', 'loseSpeech', 'Come on, you stupid PokeNav! Charge already!'] => 'Komm schon, du blöder PokéNav! Lad endlich!',
    ['Kameron', 'TechNerd', 'introSpeech', 'I\'ve been working on my latest invention!'] => 'Ich arbeite gerade an meiner neuesten Erfindung!',
    ['Kameron', 'TechNerd', 'winSpeech', 'It\'s an ultra-high-speed charger for any battery!'] => 'Ein ultraschnelles Ladegerät für jeden Akku!',
    ['Kameron', 'TechNerd', 'loseSpeech', 'But you didn\'t get to hear about it!'] => 'Aber du hast gar nicht mehr davon erfahren!',
