    ['Emilee', 'COOLTRAINER_Female', 'winSpeech', 'Why do you look so much like the Champion but fight so badly?'] => 'Wieso siehst du dem Champ so ähnlich, kämpfst aber so schlecht?',
    ['Emilee', 'COOLTRAINER_Female', 'loseSpeech', 'I met a celebrity!'] => 'Ich hab einen Promi getroffen!',
    ['Josie', 'COOLTRAINER_Female', 'introSpeech', 'Which color scarf do you think I should buy my Pokemon?'] => 'In welcher Farbe soll ich meinem Pokémon einen Schal kaufen?',
    ['Josie', 'COOLTRAINER_Female', 'winSpeech', 'This is a sign! I\'ll buy them both!'] => 'Das ist ein Zeichen! Ich kauf beide!',
    ['Josie', 'COOLTRAINER_Female', 'loseSpeech', 'I saw a green one in the Department Store, but I also saw a red one online...'] => 'Im Kaufhaus hab ich einen grünen gesehen, aber online auch einen roten...',
    ['Torre', 'COOLTRAINER_Male', 'introSpeech', 'How much do you know about Grass-type Pokemon?'] => 'Wie viel weißt du über Pflanzen-Pokémon?',
    ['Torre', 'COOLTRAINER_Male', 'winSpeech', 'I\'m trying to raise a Flabebe, but- Wait, what do you mean that\'s not a Grass-type?'] => 'Ich ziehe gerade ein Flabébé auf, aber—Moment, wie meinst du, das ist kein Pflanzen-Pokémon?',
    ['Torre', 'COOLTRAINER_Male', 'loseSpeech', 'More than me, I bet...'] => 'Bestimmt mehr als ich...',
    ['Skyler', 'COOLTRAINER_Male', 'introSpeech', 'Let me ingrain my battle style into your memory.'] => 'Ich präge dir meinen Kampfstil ins Gedächtnis ein.',
    ['Skyler', 'COOLTRAINER_Male', 'winSpeech', 'I\'m unforgettable now!'] => 'Jetzt bin ich unvergesslich!',
    ['Skyler', 'COOLTRAINER_Male', 'loseSpeech', 'That was pretty rude!'] => 'Das war ziemlich unhöflich!',
    ['Ruth', 'RANGERF', 'introSpeech', 'Life is a carnival!'] => 'Das Leben ist ein Jahrmarkt!',
    ['Ruth', 'RANGERF', 'winSpeech', 'Life is a carnival, and I just won the top prize!'] => 'Das Leben ist ein Jahrmarkt, und ich hab gerade den Hauptpreis gewonnen!',
    ['Ruth', 'RANGERF', 'loseSpeech', 'Let me off the ride!'] => 'Lasst mich aussteigen!',
    ['Melody', 'RANGERF', 'introSpeech', 'So this is what a real battle\'s like!'] => 'Also so fühlt sich ein echter Kampf an!',
    ['Melody', 'RANGERF', 'winSpeech', 'If I win enough, maybe Mom won\'t worry so much...'] => 'Wenn ich genug gewinne, macht Mom sich vielleicht nicht mehr so viele Sorgen...',
    ['Melody', 'RANGERF', 'loseSpeech', 'I think I\'ll go for a swim now...'] => 'Ich glaub, ich geh jetzt schwimmen...',
    ['Pedro', 'SWIMMERBOI', 'introSpeech', 'Hey! You ever been white-water swimming before?'] => 'Hey! Warst du schon mal Wildwasser-Schwimmen?',
    ['Pedro', 'SWIMMERBOI', 'winSpeech', 'It\'s pretty extreme. I doubt your Pokemon are strong enough to handle it.'] => 'Das ist ganz schön extrem. Ich bezweifle, dass deine Pokémon das schaffen.',
    ['Pedro', 'SWIMMERBOI', 'loseSpeech', 'It\'s pretty extreme, but my Pokemon protect me!'] => 'Ganz schön extrem, aber meine Pokémon beschützen mich!',
    ['Erick', 'SWIMMERBOI', 'introSpeech', 'I\'m more of a techie, but sometimes I like to take a break.'] => 'Ich bin eher ein Technikfreak, aber manchmal mach ich gern Pause.',
    ['Erick', 'SWIMMERBOI', 'winSpeech', 'I guess I\'m awesome whichever Pokemon I battle with!'] => 'Wohl egal, mit welchen Pokémon ich kämpfe – ich bin einfach klasse!',
    ['Erick', 'SWIMMERBOI', 'loseSpeech', 'I guess I should\'ve practiced more with these Pokemon!'] => 'Ich hätte mit diesen Pokémon wohl mehr üben sollen!',
    ['Elaine', 'SWIMMERGRIL', 'introSpeech', 'Can you come back later? I just want to relax right now.'] => 'Kannst du später wiederkommen? Ich will mich gerade nur entspannen.',
    ['Elaine', 'SWIMMERGRIL', 'winSpeech', 'Thanks. Just a few more minutes of rest...'] => 'Danke. Nur noch ein paar Minuten ausruhen...',
    ['Elaine', 'SWIMMERGRIL', 'loseSpeech', 'Well, I\'m all riled up now!'] => 'Na toll, jetzt bin ich hellwach!',
    ['Joyce', 'SWIMMERGRIL', 'introSpeech', 'I want to be a Primarina when I grow up!'] => 'Wenn ich groß bin, will ich eine Primarene sein!',
    ['Joyce', 'SWIMMERGRIL', 'winSpeech', 'You la-la-la looooooost!'] => 'Du hast la-la-la verlooooren!',
    ['Joyce', 'SWIMMERGRIL', 'loseSpeech', 'Tra la la.... I looooooost!'] => 'Tra-la-la... ich ha-ha-be verlooooren!',
    ['Todd', 'PoliceOfficer', 'introSpeech', 'Why can\'t I find any good cafes?'] => 'Warum finde ich keine guten Cafés?',
    ['Todd', 'PoliceOfficer', 'winSpeech', 'Maybe I\'ll treat myself to Spyce tonight.'] => 'Vielleicht gönn ich mir heute Abend was bei Spyce.',
    ['Todd', 'PoliceOfficer', 'loseSpeech', 'Hey, kid, do you know if Mika\'s Coffee has a branch here?'] => 'Hey, Kleiner, weißt du, ob Mika\'s Coffee hier eine Filiale hat?',
    ['Gavin', 'PoliceOfficer', 'introSpeech', 'This is nice. Just some good music and a few battles.'] => 'Schön hier. Gute Musik und ein paar Kämpfe.',
    ['Gavin', 'PoliceOfficer', 'winSpeech', 'So much better than when I was stationed in Beryl!'] => 'Viel besser als damals, als ich in Beryl stationiert war!',
    ['Gavin', 'PoliceOfficer', 'loseSpeech', 'Losing doesn\'t get any easier, though!'] => 'Verlieren wird trotzdem nicht leichter!',
    ['Malory', 'COOLTRAINER_Female', 'introSpeech', 'Hey guuuys, we\'re live from the Reborn region! Just about to have a battle in the famous Reborn Nightclub! Wish me luck!'] => 'Hey, Leuteee, wir sind live aus der Reborn-Region! Gleich kämpfe ich im berühmten Nachtclub von Reborn! Drückt mir die Daumen!',
    ['Malory', 'COOLTRAINER_Female', 'winSpeech', 'Another win for MaloryMoo92! Thanks to all my watchers for supporting me~!'] => 'Noch ein Sieg für MaloryMoo92! Danke an alle Zuschauer für eure Unterstützung~!',
    ['Malory', 'COOLTRAINER_Female', 'loseSpeech', 'Hey, you were awesome! Can I get a quote for all my watchers?'] => 'Hey, du warst echt klasse! Hast du einen Spruch für meine Zuschauer?',
    ['Esther', 'COOLTRAINER_Female', 'introSpeech', 'It\'s my birthday today!'] => 'Heute hab ich Geburtstag!',
    ['Esther', 'COOLTRAINER_Female', 'winSpeech', 'A win is a nice enough present!'] => 'Ein Sieg ist doch ein nettes Geschenk!',
    ['Esther', 'COOLTRAINER_Female', 'loseSpeech', 'It\'s my birthday but I have to give you money...'] => 'Ich hab Geburtstag und muss dir trotzdem Geld geben...',
    ['Oscar', 'AQUA2', 'introSpeech', 'Ugh... Do we have to do this?'] => 'Ugh... Müssen wir das echt machen?',
    ['Oscar', 'AQUA2', 'winSpeech', 'Haha! Is that all you got?'] => 'Haha! War das schon alles?',
    ['Oscar', 'AQUA2', 'loseSpeech', 'Another loss... Figures'] => 'Schon wieder verloren... War ja klar.',
    ['Wilson', 'AQUA2', 'introSpeech', 'Get ready. I ain\'t here to play ball.'] => 'Mach dich bereit. Ich bin nicht hier, um Ball zu spielen.',
    ['Wilson', 'AQUA2', 'winSpeech', 'Told you.'] => 'Hab ich doch gesagt.',
    ['Wilson', 'AQUA2', 'loseSpeech', '\'Pparently I was the one who wasn\'t ready! '] => 'Offenbar war ich derjenige, der nicht bereit war! ',
    ['Clare', 'Doxy', 'introSpeech', 'Oooh, you look tough!'] => 'Oooh, du siehst stark aus!',
    ['Clare', 'Doxy', 'winSpeech', 'I hate when I\'m wrong...'] => 'Ich hasse es, wenn ich mich irre...',
    ['Clare', 'Doxy', 'loseSpeech', 'You were super tough! Can I get your autograph?'] => 'Du warst super stark! Krieg ich ein Autogramm?',
    ['Tess', 'Doxy', 'introSpeech', 'I make Pokemon keychains. If you win, I\'ll give you a free customized keychain!'] => 'Ich mache Pokémon-Schlüsselanhänger. Wenn du gewinnst, schenke ich dir einen nach Wunsch!',
    ['Tess', 'Doxy', 'winSpeech', 'Better luck next time! You should still check out my shop when I open it, though!'] => 'Vielleicht klappt\'s nächstes Mal! Schau trotzdem in meinem Laden vorbei, wenn er öffnet!',
    ['Tess', 'Doxy', 'loseSpeech', 'That was great! Okay, so let\'s get your contact info for that commission...'] => 'Das war toll! Also, gib mir mal deine Kontaktdaten für den Auftrag...',
    ['Leon', 'POACHERM', 'introSpeech', 'I don\'t care what those numbskulls say, I\'m the best trainer here.'] => 'Mir egal, was diese Hohlköpfe sagen, ich bin hier der beste Trainer.',
    ['Leon', 'POACHERM', 'winSpeech', 'Nothing can hold me down!'] => 'Nichts kann mich unterkriegen!',
    ['Leon', 'POACHERM', 'loseSpeech', 'Maybe they had a point. Hey, Mom, Dad, I\'m sorry for callin\' you numbskulls!'] => 'Vielleicht hatten sie recht. Hey, Mom, Dad, tut mir leid, dass ich euch Hohlköpfe genannt hab!',
    ['Melih', 'POACHERM', 'introSpeech', 'Man, this is the life!'] => 'Mann, das ist das Leben!',
    ['Melih', 'POACHERM', 'winSpeech', 'Haha, that sad face looks good on you!'] => 'Haha, dein trauriges Gesicht steht dir gut!',
    ['Melih', 'POACHERM', 'loseSpeech', 'Even losin\'s not so bad here!'] => 'Selbst Verlieren ist hier gar nicht so schlimm!',
    ['Vince', 'AceTrainerM', 'introSpeech', 'Let\'s crash this party!'] => 'Lass uns die Party crashen!',
    ['Vince', 'AceTrainerM', 'winSpeech', 'Let\'s keep the party going!'] => 'Feiern wir weiter!',
    ['Vince', 'AceTrainerM', 'loseSpeech', 'Man, why d\'you have to be such a party pooper?'] => 'Mann, warum musst du so ein Spielverderber sein?',
    ['Bryon', 'AceTrainerM', 'introSpeech', 'So if Swift has 60 base power, and I factor in- wait, I\'m not ready yet!'] => 'Wenn Sternschauer eine Stärke von 60 hat und ich noch einberechne—Moment, ich bin noch nicht bereit!',
    ['Bryon', 'AceTrainerM', 'winSpeech', 'I\'m learning!'] => 'Ich lerne dazu!',
    ['Bryon', 'AceTrainerM', 'loseSpeech', 'My calculations were wrong...'] => 'Meine Berechnungen waren falsch...',
    ['Ava', 'POACHERF', 'introSpeech', 'I am a treasure of this world!'] => 'Ich bin ein Schatz dieser Welt!',
    ['Ava', 'POACHERF', 'winSpeech', 'I am positively peerless!'] => 'Ich bin einfach unübertroffen!',
    ['Ava', 'POACHERF', 'loseSpeech', 'How could you treat me this way!? '] => 'Wie kannst du mich nur so behandeln!? ',
    ['Miriam', 'POACHERF', 'introSpeech', 'Why are you looking at me that way?'] => 'Warum schaust du mich so an?',
    ['Miriam', 'POACHERF', 'winSpeech', 'Quit with that look!'] => 'Hör auf, so zu gucken!',
    ['Miriam', 'POACHERF', 'loseSpeech', 'Your gaze is unnerving...'] => 'Dein Blick ist unheimlich...',
    ['Carrie', 'AceTrainerF', 'introSpeech', 'Please don\'t shout at me...'] => 'Bitte schrei mich nicht an...',
    ['Carrie', 'AceTrainerF', 'winSpeech', 'Thank you for a nice battle...'] => 'Danke für den netten Kampf...',
    ['Carrie', 'AceTrainerF', 'loseSpeech', 'YOU JERK-- oops, I shouted...'] => 'DU IDIOT—ups, ich hab geschrien...',
    ['Lilly', 'AceTrainerF', 'introSpeech', 'The trainers here have been boring me. Are you more interesting?'] => 'Die Trainer hier langweilen mich. Bist du interessanter?',
    ['Lilly', 'AceTrainerF', 'winSpeech', 'Yawn. Still bored!'] => 'Gähn. Immer noch langweilig!',
    ['Lilly', 'AceTrainerF', 'loseSpeech', 'Definitely not boring! Maybe a little too much!'] => 'Definitiv nicht langweilig! Vielleicht sogar ein bisschen zu sehr!',
    ['Joey', 'Orderly', 'introSpeech', 'Don\'t let your wins make you comfortable. '] => 'Lass dich von deinen Siegen nicht in Sicherheit wiegen. ',
    ['Joey', 'Orderly', 'winSpeech', 'Battles here are easy to win!'] => 'Kämpfe gewinnt man hier leicht!',
    ['Joey', 'Orderly', 'loseSpeech', 'Clearly, there\'s no shortage of skill here!'] => 'An Können mangelt\'s hier offenbar nicht!',
    ['Chaz', 'Orderly', 'introSpeech', 'I hate cleaning, but the battling\'s not so bad. '] => 'Putzen hasse ich, aber Kämpfen ist ganz okay. ',
    ['Chaz', 'Orderly', 'winSpeech', 'Heck yeah! '] => 'Oh ja! ',
    ['Chaz', 'Orderly', 'loseSpeech', 'Did you have to win so fast? Now I have to go back to cleaning...'] => 'Musste dein Sieg so schnell kommen? Jetzt muss ich wieder putzen...',
    ['Nelson', 'Orderly', 'introSpeech', 'All right, let\'s keep it going!'] => 'Na los, weiter geht\'s!',
    ['Nelson', 'Orderly', 'winSpeech', 'Oh hey, I did it. Good battle, kid. '] => 'Oh, hey, ich hab\'s geschafft. Guter Kampf, Kleiner. ',
    ['Nelson', 'Orderly', 'loseSpeech', 'Eh. I\'d better go check on that lazy Chaz...'] => 'Hm. Ich sollte mal nach dem faulen Chaz sehen...',
    ['Shania', 'OrderlyF', 'introSpeech', 'You think you\'re special?'] => 'Du glaubst, du bist was Besonderes?',
    ['Shania', 'OrderlyF', 'winSpeech', 'That didn\'t impress me much.'] => 'Das hat mich nicht sonderlich beeindruckt.',
    ['Shania', 'OrderlyF', 'loseSpeech', 'You\'re something else!'] => 'Du bist echt nicht ohne!',
    ['Stella', 'OrderlyF', 'introSpeech', 'Have you ever been to Unova?'] => 'Warst du schon mal in Einall?',
    ['Stella', 'OrderlyF', 'winSpeech', 'You should go! '] => 'Da solltest du mal hin! ',
    ['Stella', 'OrderlyF', 'loseSpeech', 'You\'re sure stronger than the trainers there...'] => 'Du bist bestimmt stärker als die Trainer dort...',
    ['Dorine', 'OrderlyF', 'introSpeech', 'Let\'s all sing a happy battling song!'] => 'Singen wir alle ein fröhliches Kampflied!',
    ['Dorine', 'OrderlyF', 'winSpeech', 'We\'re finishing our happy battling song!'] => 'Wir singen unser fröhliches Kampflied zu Ende!',
    ['Dorine', 'OrderlyF', 'loseSpeech', 'B-but you were singing off key! '] => 'A-aber du hast schief gesungen! ',
    ['Maddox', 'MAGMA1', 'introSpeech', 'By the time I\'m finished with you, you\'ll never want to battle again!'] => 'Wenn ich mit dir fertig bin, willst du nie wieder kämpfen!',
    ['Maddox', 'MAGMA1', 'winSpeech', 'I will reign supreme!'] => 'Ich werde herrschen!',
    ['Maddox', 'MAGMA1', 'loseSpeech', 'Didn\'t buy it, huh? Ah well.'] => 'Du hast es mir nicht abgekauft, was? Na ja.',
    ['Davin', 'MAGMA1', 'introSpeech', 'Even now that the city\'s doin\' better, it\'s hard to find strong Pokemon here.'] => 'Selbst jetzt, wo es der Stadt besser geht, ist es schwer, hier starke Pokémon zu finden.',
    ['Davin', 'MAGMA1', 'winSpeech', 'Like, why aren\'t there any Salamence or Hydreigon in the city?'] => 'Also echt, warum gibt\'s in der Stadt keine Brutalanda oder Trikephalo?',
    ['Davin', 'MAGMA1', 'loseSpeech', 'Where\'d you get that team!?'] => 'Wo hast du bitte dieses Team her!?',
    ['Trevon', 'MAGMA1', 'introSpeech', 'Hey! Have you heard about our Lord and Savior Groudon today?'] => 'Hey! Hast du heute schon von unserem Herrn und Erlöser Groudon gehört?',
    ['Trevon', 'MAGMA1', 'winSpeech', 'It made the land! It made me strong!'] => 'Es hat das Land erschaffen! Es hat mich stark gemacht!',
    ['Trevon', 'MAGMA1', 'loseSpeech', 'Okay, okay, I\'m leaving!'] => 'Schon gut, schon gut, ich geh ja!',
    ['Mateo', 'BLACKBELT', 'introSpeech', 'This won\'t take long...'] => 'Das dauert nicht lang ...',
    ['Mateo', 'BLACKBELT', 'winSpeech', 'Easy. '] => 'Ein Kinderspiel.',
    ['Mateo', 'BLACKBELT', 'loseSpeech', '...Well, I wasn\'t wrong!'] => '... Na ja, ich lag nicht falsch!',
    ['Bret', 'BLACKBELT', 'introSpeech', 'Y\'know what bothers me about being a Blackbelt?'] => 'Weißt du, was mich daran stört, Schwarzgurt zu sein?',
    ['Bret', 'BLACKBELT', 'winSpeech', 'I just don\'t get why the strongest rank has the dullest belt!'] => 'Ich versteh einfach nicht, warum der höchste Rang den langweiligsten Gürtel hat!',
    ['Bret', 'BLACKBELT', 'loseSpeech', 'Well, losing, for one thing...'] => 'Na ja, zum Beispiel zu verlieren ...',
    ['Raul', 'BLACKBELT', 'introSpeech', 'You\'re safe... Nothing can harm you...'] => 'Du bist in Sicherheit ... Nichts kann dir etwas anhaben ...',
    ['Raul', 'BLACKBELT', 'winSpeech', 'Get stronger! That\'s all I ask before you challenge me again.'] => 'Werd stärker! Mehr verlange ich nicht, bevor du mich wieder herausforderst.',
    ['Raul', 'BLACKBELT', 'loseSpeech', 'I guess I should forget these wide-eyed dreams of winning...'] => 'Ich sollte wohl diese naiven Träume vom Sieg vergessen ...',
    ['Kay', 'BATTLEGIRL', 'introSpeech', 'Man, this is a lot of battles...'] => 'Mann, das sind ganz schön viele Kämpfe ...',
    ['Kay', 'BATTLEGIRL', 'winSpeech', 'I\'m tired, but it feels good!'] => 'Ich bin müde, aber es fühlt sich gut an!',
    ['Kay', 'BATTLEGIRL', 'loseSpeech', 'Victoria sending us here was brutal!'] => 'Dass Victoria uns hierhergeschickt hat, war echt brutal!',
    ['Mimi', 'BATTLEGIRL', 'introSpeech', 'Get out of the way, please.'] => 'Geh bitte aus dem Weg.',
    ['Mimi', 'BATTLEGIRL', 'winSpeech', 'Merci for letting me through.'] => 'Merci, dass du mich durchgelassen hast.',
    ['Mimi', 'BATTLEGIRL', 'loseSpeech', 'You defeat Mimi? You toss her Pokemon away!? Jail for Trainer!'] => 'Du besiegst Mimi? Du wirfst ihre Pokémon weg!? Ab ins Gefängnis mit Trainer!',
    ['Alana', 'BATTLEGIRL', 'introSpeech', 'I am the Striking Pyroar...'] => 'Ich bin das schlagkräftige Pyroleo ...',
    ['Alana', 'BATTLEGIRL', 'winSpeech', 'Feel my blazing conviction!'] => 'Spür meine lodernde Entschlossenheit!',
    ['Alana', 'BATTLEGIRL', 'loseSpeech', 'You must be the Charging Lapras...'] => 'Du musst das stürmische Lapras sein ...',
    ['Alexas', 'PoliceOfficer', 'introSpeech', 'Ah, a youngster! Good to meet you, young Trainer!'] => 'Ah, ein Jungspund! Freut mich, dich kennenzulernen, junger Trainer!',
    ['Alexas', 'PoliceOfficer', 'winSpeech', 'That was a fine showing!'] => 'Das war eine starke Vorstellung!',
    ['Alexas', 'PoliceOfficer', 'loseSpeech', 'Have you considered a job in law enforcement? '] => 'Schon mal über einen Job bei der Polizei nachgedacht?',
    ['Weston', 'PoliceOfficer', 'introSpeech', 'Hey, buddy... You seen my Growlithe?'] => 'Hey, Kumpel ... Hast du mein Fukano gesehen?',
    ['Weston', 'PoliceOfficer', 'winSpeech', ' No? Okay, thanks anyway. '] => 'Nein? Na gut, trotzdem danke.',
    ['Weston', 'PoliceOfficer', 'loseSpeech', 'He hates when I don\'t let him battle... Kerry, here boy!'] => 'Er hasst es, wenn ich ihn nicht kämpfen lasse ... Kerry, hierher, Junge!',
    ['Monroe', 'PoliceOfficer', 'introSpeech', 'Don\'t you look at me like that! I know you think I\'m an old man! Well, I\'ve got news for you!'] => 'Sieh mich nicht so an! Ich weiß, du hältst mich für einen alten Mann! Aber ich hab Neuigkeiten für dich!',
    ['Monroe', 'PoliceOfficer', 'winSpeech', 'I\'m not old! I\'m a seasoned veteran!'] => 'Ich bin nicht alt! Ich bin ein erfahrener Veteran!',
    ['Monroe', 'PoliceOfficer', 'loseSpeech', '...Maybe I am too old for this. '] => '... Vielleicht bin ich wirklich zu alt für sowas.',
    ['Nadia', 'NatureGirl', 'introSpeech', 'You know Adrienn, right? Do you think you could get a message to xem?'] => 'Du kennst Adrienn, oder? Könntest du xem eine Nachricht ausrichten?',
    ['Nadia', 'NatureGirl', 'winSpeech', 'Let xem know I really appreciate xyr work. This place finally feels like home again. '] => 'Sag xem, wie sehr ich xyr Arbeit schätze. Hier fühlt es sich endlich wieder wie ein Zuhause an.',
    ['Nadia', 'NatureGirl', 'loseSpeech', 'I wanted to send a thank you note for all xe\'s done to restore the city!'] => 'Ich wollte Adrienn eine Dankeskarte schicken, für all die Arbeit am Wiederaufbau der Stadt!',
    ['Miranda', 'NatureGirl', 'introSpeech', 'Let me find happiness through this battle!'] => 'Lass mich in diesem Kampf mein Glück finden!',
    ['Miranda', 'NatureGirl', 'winSpeech', 'You\'ll be okay. In time you\'ll learn how to lose with grace. '] => 'Schon gut. Mit der Zeit lernst du, mit Würde zu verlieren.',
    ['Miranda', 'NatureGirl', 'loseSpeech', 'There\'s just no telling how far you\'ll go to win!'] => 'Wer weiß schon, wie weit du gehen würdest, um zu gewinnen!',
    ['Emma', 'NatureGirl', 'introSpeech', 'Hey, what\'s with the long face?'] => 'Hey, warum ziehst du so ein langes Gesicht?',
    ['Emma', 'NatureGirl', 'winSpeech', 'Try not to worry about it too much, okay?'] => 'Mach dir nicht zu viele Sorgen, okay?',
    ['Emma', 'NatureGirl', 'loseSpeech', 'I want to sing a song of sorrow now...'] => 'Jetzt möchte ich ein trauriges Lied singen ...',
    ['Rolando', 'PSYCHIC_Male', 'introSpeech', 'It is I, Roserade Mask!'] => 'Ich bin\'s, die Roserade-Maske!',
    ['Rolando', 'PSYCHIC_Male', 'winSpeech', 'My work here is finished!'] => 'Meine Arbeit hier ist getan!',
    ['Rolando', 'PSYCHIC_Male', 'loseSpeech', 'But I didn\'t even get to do anything!'] => 'Aber ich bin ja gar nicht dazu gekommen, etwas zu tun!',
    ['Stanly', 'PSYCHIC_Male', 'introSpeech', 'Let me read your aura...'] => 'Lass mich deine Aura lesen ...',
    ['Stanly', 'PSYCHIC_Male', 'winSpeech', 'Your aura is as green as you are!'] => 'Deine Aura ist so grün wie du!',
    ['Stanly', 'PSYCHIC_Male', 'loseSpeech', 'I\'ve never seen such an aura before!'] => 'So eine Aura habe ich noch nie gesehen!',
    ['Dario', 'PSYCHIC_Male', 'introSpeech', 'There is no such thing as luck! I win with pure skill! '] => 'Glück gibt\'s nicht! Ich siege allein mit Können!',
    ['Dario', 'PSYCHIC_Male', 'winSpeech', 'And now we see who\'s the more skilled!'] => 'Jetzt sehen wir, wer von uns mehr draufhat!',
    ['Dario', 'PSYCHIC_Male', 'loseSpeech', 'Psh. You got lucky. '] => 'Pff. Du hattest einfach Glück.',
    ['Karlee', 'PSYCHIC_Female', 'introSpeech', 'I have a feeling I\'m about to win!'] => 'Ich hab so ein Gefühl, dass ich gleich gewinne!',
    ['Karlee', 'PSYCHIC_Female', 'winSpeech', 'Don\'t take it too hard. I\'ve never been wrong before!'] => 'Nimm\'s nicht so schwer. Ich lag noch nie falsch!',
    ['Karlee', 'PSYCHIC_Female', 'loseSpeech', 'W-what? But my intuition...'] => 'W-was? Aber meine Intuition ...',
    ['Jaylin', 'PSYCHIC_Female', 'introSpeech', 'Please impress me. '] => 'Beeindruck mich bitte.',
    ['Jaylin', 'PSYCHIC_Female', 'winSpeech', 'Another one too weak...'] => 'Schon wieder einer zu schwach ...',
    ['Jaylin', 'PSYCHIC_Female', 'loseSpeech', 'You\'ve certainly got what it takes...'] => 'Du hast definitiv das Zeug dazu ...',
    ['Ingrid', 'PSYCHIC_Female', 'introSpeech', 'Are you ready to lose?'] => 'Bist du bereit zu verlieren?',
    ['Ingrid', 'PSYCHIC_Female', 'winSpeech', 'You\'ll see me in your dreams!'] => 'Du wirst mir in deinen Träumen begegnen!',
    ['Ingrid', 'PSYCHIC_Female', 'loseSpeech', 'You went overboard...'] => 'Du hast es übertrieben ...',
    ['Delilah', 'CultistF', 'introSpeech', 'Hey there!'] => 'Na, hallo!',
    ['Delilah', 'CultistF', 'winSpeech', 'Definitely not the one.'] => 'Ganz sicher nicht die gesuchte Person.',
    ['Delilah', 'CultistF', 'loseSpeech', 'No, you\'re not the one...'] => 'Nein, du bist es nicht ...',
    ['Carly', 'CultistF', 'introSpeech', 'Hey, you know where a gal can get a Soda Pop around here?'] => 'Hey, weißt du, wo man hier \'nen Sprudel kriegt?',
    ['Carly', 'CultistF', 'winSpeech', 'Never mind, never mind.'] => 'Schon gut, schon gut.',
    ['Carly', 'CultistF', 'loseSpeech', 'I\'m really thirsty!'] => 'Ich hab echt Durst!',
    ['Lexie', 'CultistF', 'introSpeech', 'Take a look at my cute Pokemon!'] => 'Sieh dir mal meine süßen Pokémon an!',
    ['Lexie', 'CultistF', 'winSpeech', 'Weren\'t they adorable?'] => 'Waren sie nicht zum Knuddeln?',
    ['Lexie', 'CultistF', 'loseSpeech', 'What do you mean they\'re not cute!? Shows how much you know!'] => 'Was heißt hier, sie sind nicht süß!? Du hast ja keine Ahnung!',
    ['Miller', 'Cultist', 'introSpeech', 'Just act like everything\'s normal, okay? Now, have you run into a cultist named Marv?'] => 'Tu einfach so, als wäre alles normal, okay? Sag mal, ist dir ein Kultist namens Marv begegnet?',
    ['Miller', 'Cultist', 'winSpeech', 'He\'s wanted for stealing large quantities of Pecha Berries...'] => 'Er wird gesucht, weil er große Mengen Pirsifbeeren gestohlen hat ...',
    ['Miller', 'Cultist', 'loseSpeech', 'It\'s fine. Don\'t worry about it. '] => 'Schon okay. Mach dir keinen Kopf.',
    ['Marv', 'Cultist', 'introSpeech', 'Y-you haven\'t seen any coppers around here, have you?'] => 'D-du hast hier doch keine Bullen gesehen, oder?',
    ['Marv', 'Cultist', 'winSpeech', 'Phew. '] => 'Puh.',
    ['Marv', 'Cultist', 'loseSpeech', 'No reason!!'] => 'Kein Grund!!',
    ['Layton', 'Cultist', 'introSpeech', 'I\'ve always loved battling...'] => 'Kämpfe haben mir schon immer gefallen ...',
    ['Layton', 'Cultist', 'winSpeech', 'Well done, really!'] => 'Wirklich gut gemacht!',
    ['Layton', 'Cultist', 'loseSpeech', 'A battle is an exquisite puzzle, is it not?'] => 'Ein Kampf ist ein kunstvolles Rätsel, nicht wahr?',
    ['Payson', 'GENTLEMAN', 'introSpeech', 'Battles are best when you go in without expectation.'] => 'Kämpfe sind am besten, wenn man ohne Erwartungen hineingeht.',
    ['Payson', 'GENTLEMAN', 'winSpeech', 'You must expect the unexpected, my friend. '] => 'Du musst mit dem Unerwarteten rechnen, mein Freund.',
    ['Payson', 'GENTLEMAN', 'loseSpeech', 'If you do not expect to win, a loss won\'t set you back much.'] => 'Wenn du nicht mit einem Sieg rechnest, wirft dich eine Niederlage nicht so sehr zurück.',
    ['Gregory', 'GENTLEMAN', 'introSpeech', 'I may appear frail... '] => 'Ich wirke vielleicht gebrechlich ...',
    ['Gregory', 'GENTLEMAN', 'winSpeech', 'Never underestimate Gregory!'] => 'Unterschätz Gregory niemals!',
    ['Gregory', 'GENTLEMAN', 'loseSpeech', 'All I need is a bit more time...'] => 'Ich brauch nur noch ein bisschen Zeit ...',
    ['Reese', 'GENTLEMAN', 'introSpeech', 'Now watch how a sweet ol\' fella like me battles!'] => 'Jetzt sieh dir mal an, wie so ein alter Charmeur wie ich kämpft!',
    ['Reese', 'GENTLEMAN', 'winSpeech', 'That battle was a treat!'] => 'Der Kampf war ein Genuss!',
    ['Reese', 'GENTLEMAN', 'loseSpeech', 'I\'m falling to pieces...'] => 'Ich zerfalle in Einzelteile ...',
    ['Mason', 'MAGMA2', 'introSpeech', 'I\'m up for a promotion. Would you mind sparring with me as practice?'] => 'Ich soll befördert werden. Würdest du zum Üben mit mir kämpfen?',
    ['Mason', 'MAGMA2', 'winSpeech', 'Thanks! I\'ll get that promotion for sure!'] => 'Danke! Die Beförderung ist mir sicher!',
    ['Mason', 'MAGMA2', 'loseSpeech', 'That was jarring...'] => 'Das war ganz schön erschütternd ...',
    ['Toby', 'MAGMA2', 'introSpeech', 'I\'m tall, right? D\'you think I can pass for an adult?'] => 'Ich bin groß, oder? Könnte ich als Erwachsener durchgehen?',
    ['Toby', 'MAGMA2', 'winSpeech', 'Hah! You got beaten by a kid!'] => 'Ha! Du wurdest von einem Kind besiegt!',
    ['Toby', 'MAGMA2', 'loseSpeech', 'This is so unfair! I\'m telling...'] => 'Das ist so unfair! Ich sag\'s ...',
    ['Dorothy', 'BEAUTY', 'introSpeech', 'I don\'t think I\'m in Pastoria anymore...'] => 'Ich glaube, ich bin nicht mehr in Weideburg ...',
    ['Dorothy', 'BEAUTY', 'winSpeech', 'The way to win was with me all along! It was you, my darling Pokemon!'] => 'Der Schlüssel zum Sieg war die ganze Zeit bei mir! Ihr wart es, meine lieben Pokémon!',
    ['Dorothy', 'BEAUTY', 'loseSpeech', 'The Trainers here are so strong! You must have a rainbow of badges!'] => 'Die Trainer hier sind so stark! Du musst einen ganzen Regenbogen an Orden haben!',
    ['Piper', 'LADY', 'introSpeech', 'Have you any interest in stargazing?'] => 'Hast du Interesse daran, Sterne zu beobachten?',
    ['Piper', 'LADY', 'winSpeech', 'The finest place I\'ve found is Teknite Ridge!'] => 'Der beste Ort, den ich gefunden habe, ist Teknite Ridge!',
    ['Piper', 'LADY', 'loseSpeech', 'Clearly, I\'m gazing at a star right now!'] => 'Offensichtlich schaue ich gerade einen Stern an!',
    ['Finn', 'EXPERT_Male', 'introSpeech', 'Let\'s just make this quick. I have a train to catch.'] => 'Machen wir\'s schnell. Ich muss meinen Zug erwischen.',
    ['Finn', 'EXPERT_Male', 'winSpeech', 'Good, thank you.'] => 'Gut, danke.',
    ['Finn', 'EXPERT_Male', 'loseSpeech', 'Perhaps I could stick around a while after all.'] => 'Vielleicht bleib ich doch noch eine Weile.',
    ['Sameer', 'SWIMMERBOI', 'introSpeech', 'I\'m at the top of my class in swimming and battles!'] => 'Ich bin in Schwimmen und Kämpfen Klassenbester!',
    ['Sameer', 'SWIMMERBOI', 'winSpeech', 'You\'re pretty good, though! Nice form!'] => 'Du bist aber ziemlich gut! Tolle Technik!',
    ['Sameer', 'SWIMMERBOI', 'loseSpeech', 'Man, I\'m glad you\'re not in my class...'] => 'Mann, bin ich froh, dass du nicht in meiner Klasse bist ...',
    ['Fiona', 'SWIMMERGRIL', 'introSpeech', 'So you\'re the one they think can defeat me? All right, give me your best. '] => 'Also, du bist die Person, von der alle glauben, dass sie mich besiegen kann? Na gut, zeig, was du draufhast.',
    ['Fiona', 'SWIMMERGRIL', 'winSpeech', 'Another weakling... No offense.'] => 'Schon wieder ein Schwächling ... Nicht böse gemeint.',
    ['Fiona', 'SWIMMERGRIL', 'loseSpeech', 'What kind of Trainer are you?!'] => 'Was bist du denn für ein Trainer?!',
    ['Gloria', 'SWIMMERGRIL', 'introSpeech', 'Ohmigosh! I\'m your number one fan! '] => 'Oh mein Gott! Ich bin dein allergrößter Fan!',
    ['Gloria', 'SWIMMERGRIL', 'winSpeech', 'I- did I really win?'] => 'I-ich hab wirklich gewonnen?',
    ['Gloria', 'SWIMMERGRIL', 'loseSpeech', 'I got defeated by the Champion themself... this is the best day of my life...'] => 'Ich wurde vom Champ höchstpersönlich besiegt ... Das ist der beste Tag meines Lebens ...',
    ['Nico', 'CUEBALL', 'introSpeech', 'Well, well, well. What d\'you think my odds are of beating you?'] => 'Na, na, na. Wie stehen wohl meine Chancen, dich zu schlagen?',
    ['Nico', 'CUEBALL', 'winSpeech', 'Every now and then, someone beats the odds. '] => 'Ab und zu schlägt jemand allen Chancen ein Schnippchen.',
    ['Nico', 'CUEBALL', 'loseSpeech', 'Nyeh. The odds were stacked against me anyway.'] => 'Nyeh. Die Chancen standen sowieso gegen mich.',
    ['Jeremy', 'CUEBALL', 'introSpeech', 'I keep perfect time, each day!'] => 'Ich halte jeden Tag die Zeit perfekt ein!',
    ['Jeremy', 'CUEBALL', 'winSpeech', 'There\'s exactly twelve minutes until my next battle...'] => 'Bis zu meinem nächsten Kampf sind es genau zwölf Minuten ...',
    ['Jeremy', 'CUEBALL', 'loseSpeech', 'My defeat took forty-seven seconds less than I predicted...'] => 'Meine Niederlage dauerte siebenundvierzig Sekunden weniger als vorhergesagt ...',
    ['Caitlin', 'COOLTRAINER_Female', 'introSpeech', 'I\'m writing a book! Try and give me some good inspiration.'] => 'Ich schreibe ein Buch! Gib mir etwas Inspiration.',
    ['Caitlin', 'COOLTRAINER_Female', 'winSpeech', 'Hmm... A sudden fateful meeting for the hero, maybe?'] => 'Hm ... Vielleicht eine schicksalhafte Begegnung für den Helden?',
    ['Caitlin', 'COOLTRAINER_Female', 'loseSpeech', 'Yes, that\'s perfect! I know just what to write next!'] => 'Ja, perfekt! Ich weiß genau, was ich als Nächstes schreibe!',
    ['Reena', 'COOLTRAINER_Female', 'introSpeech', 'I\'m training in Pokemon first aid. Let me take a look at your Pokemon for you.'] => 'Ich lerne Pokémon-Erste-Hilfe. Lass mich deine Pokémon mal ansehen.',
    ['Reena', 'COOLTRAINER_Female', 'winSpeech', 'Well, they were fine before my Pokemon beat them all up...'] => 'Na ja, ihnen ging\'s gut, bevor meine Pokémon sie vermöbelt haben ...',
    ['Reena', 'COOLTRAINER_Female', 'loseSpeech', 'They\'re definitely all in top battling shape!'] => 'Sie sind definitiv alle in bester Kampfform!',
    ['Avery', 'StreetRat', 'introSpeech', 'Personally, I don\'t think Flying-types should even be allowed in here!'] => 'Ich finde, Flug-Pokémon sollten hier gar nicht erst erlaubt sein!',
    ['Avery', 'StreetRat', 'winSpeech', 'My Bugs can defeat even the most vicious of them!'] => 'Meine Käfer können selbst die wildesten von ihnen besiegen!',
    ['Avery', 'StreetRat', 'loseSpeech', 'They moult, they screech, and they frighten my precious Bugs!'] => 'Sie mausern sich, kreischen und erschrecken meine geliebten Käfer!',
    ['Liam', 'StreetRat', 'introSpeech', 'Say... You\'re not looking so hot.'] => 'Sag mal ... Du siehst nicht gerade gut aus.',
    ['Liam', 'StreetRat', 'winSpeech', 'You might want to take a break, hey?'] => 'Vielleicht solltest du eine Pause machen, hm?',
    ['Liam', 'StreetRat', 'loseSpeech', 'Appearances aren\'t everything, I guess...'] => 'Aufs Aussehen kommt\'s wohl nicht immer an ...',
    ['Theo', 'FISHERMAN', 'introSpeech', 'Care to cast your line?'] => 'Willst du deine Angel auswerfen?',
    ['Theo', 'FISHERMAN', 'winSpeech', 'I lured that victory to me, easy!'] => 'Den Sieg hab ich ganz leicht an Land gezogen!',
    ['Theo', 'FISHERMAN', 'loseSpeech', 'I won\'t be so easily baited next time!'] => 'Nächstes Mal geh ich nicht so leicht an den Haken!',
    ['Bailey', 'FISHERMAN', 'introSpeech', 'You ever been to Hoppy Town?'] => 'Warst du schon mal in Hoppy Town?',
    ['Bailey', 'FISHERMAN', 'winSpeech', 'You\'d be surprised what a lifetime of Jump tourneys can prepare ya for!'] => 'Du wärst überrascht, worauf dich ein Leben voller Sprungturniere vorbereiten kann!',
    ['Bailey', 'FISHERMAN', 'loseSpeech', 'We\'re not much for battle, but you\'ve never seen prettier Pokemon!'] => 'Kämpfen ist nicht so unser Ding, aber schönere Pokémon hast du noch nie gesehen!',
    ['Hugo', 'KNIGHT', 'introSpeech', 'Before we battle, let us set the stage!'] => 'Bevor wir kämpfen, lass uns die Bühne bereiten!',
    ['Hugo', 'KNIGHT', 'winSpeech', 'This unassuming bard takes home the prize!'] => 'Dieser unscheinbare Barde nimmt den Preis mit nach Hause!',
    ['Hugo', 'KNIGHT', 'loseSpeech', 'A well-intended loss is not a shame.'] => 'Mit guter Absicht zu verlieren, ist keine Schande.',
    ['Knight', 'KNIGHT', 'introSpeech', 'I hereby declare this day open.'] => 'Hiermit erkläre ich diesen Tag für eröffnet.',
    ['Knight', 'KNIGHT', 'winSpeech', 'I hereby declare you closed.'] => 'Hiermit erkläre ich dich für erledigt.',
    ['Knight', 'KNIGHT', 'loseSpeech', 'I hereby declare this day closed.'] => 'Hiermit erkläre ich diesen Tag für beendet.',
    ['Bryce', 'KNIGHT', 'introSpeech', 'Do you know where a man can find a Pokemon spa?'] => 'Weißt du, wo man ein Pokémon-Wellnessbad findet?',
    ['Bryce', 'KNIGHT', 'winSpeech', 'I must find a place for my dear partner to relax!'] => 'Ich muss einen Ort finden, an dem sich mein lieber Partner entspannen kann!',
    ['Bryce', 'KNIGHT', 'loseSpeech', 'There are two, and close to here? Many thanks!'] => 'Gleich zwei, und ganz in der Nähe? Vielen Dank!',
    ['Gideon', 'PoliceOfficer', 'introSpeech', 'How do you do, fellow youth?'] => 'Wie geht\'s, werte Jugend?',
    ['Gideon', 'PoliceOfficer', 'winSpeech', 'I am the hopscotch and battle MASTER!'] => 'Ich bin der Himmel-und-Hölle-und-Kampf-MEISTER!',
    ['Gideon', 'PoliceOfficer', 'loseSpeech', 'Keep away from the \'Rare Candy\'!'] => 'Finger weg von den Sonderbonbons!',
    ['Triston', 'PoliceOfficer', 'introSpeech', 'Have you ever noticed this place looks like a fire hazard? Pretty sure I smell smoke...'] => 'Ist dir aufgefallen, dass dieser Ort ein einziger Brandherd ist? Ich rieche Rauch ...',
    ['Triston', 'PoliceOfficer', 'winSpeech', 'See? It\'s \'cause I\'m on fire today!'] => 'Siehst du? Ich bin heute einfach on fire!',
    ['Triston', 'PoliceOfficer', 'loseSpeech', 'See? It\'s \'cause you\'re on fire today!'] => 'Siehst du? Du bist heute einfach on fire!',
    ['Charles', 'GUITARIST', 'introSpeech', 'Hey, d\'you want to be in my band?'] => 'Hey, willst du in meiner Band sein?',
    ['Charles', 'GUITARIST', 'winSpeech', 'Never mind. I don\'t think you\'re ready. '] => 'Schon gut. Ich glaube, du bist noch nicht so weit.',
    ['Charles', 'GUITARIST', 'loseSpeech', 'On second thought, you might drown the others out...'] => 'Andererseits übertönst du vielleicht noch die anderen ...',
    ['Raymond', 'GUITARIST', 'introSpeech', 'Prepare to be wowed.'] => 'Mach dich auf was gefasst.',
    ['Raymond', 'GUITARIST', 'winSpeech', 'Devastatingly musical and a showstopping battler? I really am the whole package!'] => 'Ein mitreißender Musiker und ein umwerfender Kämpfer? Ich bin echt das Gesamtpaket!',
    ['Raymond', 'GUITARIST', 'loseSpeech', 'I guess a cat can\'t be dazzlingly talented in everything...'] => 'Ich schätze, eine Katze kann nicht in allem glänzen ...',
    ['Dirk', 'Casanova', 'introSpeech', 'Say... How about we go watch the sunset together after this?'] => 'Sag mal ... Wie wär\'s, wenn wir nachher zusammen den Sonnenuntergang anschauen?',
    ['Dirk', 'Casanova', 'winSpeech', 'Come on, my feathered beauties!'] => 'Kommt schon, meine gefiederten Schönheiten!',
    ['Dirk', 'Casanova', 'loseSpeech', 'You? No, no! I was talking to my Pokemon!'] => 'Du? Nein, nein! Ich meinte meine Pokémon!',
    ['Harold', 'Casanova', 'introSpeech', 'Okay, it\'s settled. If I win here, I\'ll ask Amaria out!'] => 'Na gut, steht fest. Wenn ich hier gewinne, frag ich Amaria nach einem Date!',
    ['Harold', 'Casanova', 'winSpeech', 'All right, I\'ll do it!'] => 'Alles klar, ich mach\'s!',
    ['Harold', 'Casanova', 'loseSpeech', 'I-I don\'t have the nerve!'] => 'I-ich trau mich nicht!',
    ['Marck-Marie', 'AQUA1', 'introSpeech', 'Hey, d\'you mind testing these cookies? I think I messed up the recipe...'] => 'Hey, würdest du diese Kekse probieren? Ich glaub, ich hab das Rezept vermasselt ...',
    ['Marck-Marie', 'AQUA1', 'winSpeech', 'The cookies are salty like you! Haha!'] => 'Die Kekse sind salzig, genau wie du! Haha!',
    ['Marck-Marie', 'AQUA1', 'loseSpeech', 'The cookies stink... and so do my battle skills!'] => 'Die Kekse sind eklig ... und meine Kampfkünste auch!',
    ['Peter', 'AQUA1', 'introSpeech', 'Hey, have you got the time? To listen to my little rhyme?'] => 'Hey, hast du ein bisschen Zeit? Für meinen kleinen Reim bereit?',
    ['Peter', 'AQUA1', 'winSpeech', 'You can\'t deny my skills are great! Now bring on the next fight! I don\'t want to wait!'] => 'Du kannst nicht leugnen, dass ich\'s draufhab! Her mit dem nächsten Kampf, ich will nicht warten!',
    ['Peter', 'AQUA1', 'loseSpeech', 'I guess the rumors must be true-- all the things they say about you!'] => 'Die Gerüchte müssen wohl stimmen – all das, was man über dich sagt!',
    ['Dev', 'HIKER', 'introSpeech', 'I love hiking, but I can\'t stand all the bugs...'] => 'Ich liebe Wanderungen, aber diese ganzen Käfer kann ich nicht ausstehen ...',
    ['Dev', 'HIKER', 'winSpeech', 'I\'ll conquer them eventually...'] => 'Irgendwann bezwinge ich sie ...',
    ['Dev', 'HIKER', 'loseSpeech', 'The bugs! They\'re overwhelming!'] => 'Die Käfer! Sie sind überall!',
    ['Corey', 'HIKER', 'introSpeech', 'I\'ve been searching for the best trail in Reborn. You\'ve been all over, right? Any suggestions?'] => 'Ich suche den besten Wanderweg in Reborn. Du warst doch überall, oder? Hast du einen Tipp?',
    ['Corey', 'HIKER', 'winSpeech', 'Maybe I should try climbing Victory Road next...'] => 'Vielleicht sollte ich als Nächstes den Siegespfad erklimmen ...',
    ['Corey', 'HIKER', 'loseSpeech', 'Hey, hey! I said I wanted a trail, not a fail!'] => 'Hey, hey! Ich wollte einen Wanderweg, keinen Reinfall!',
    ['Andre', 'HARDHAT', 'introSpeech', 'Last battle before break!'] => 'Letzter Kampf vor der Pause!',
    ['Andre', 'HARDHAT', 'winSpeech', 'Nice! The guys owe me a burger now!'] => 'Klasse! Die Jungs schulden mir jetzt einen Burger!',
    ['Andre', 'HARDHAT', 'loseSpeech', 'All right, back to building...'] => 'Na gut, zurück an die Arbeit ...',
    ['Ferris', 'HARDHAT', 'introSpeech', 'I may be just a builder, but I just know I can beat ya!'] => 'Ich bin vielleicht nur Bauarbeiter, aber ich weiß einfach, dass ich dich schlagen kann!',
    ['Ferris', 'HARDHAT', 'winSpeech', 'What\'d I say?'] => 'Was hab ich gesagt?',
    ['Ferris', 'HARDHAT', 'loseSpeech', 'All right, got a bit too confident there...'] => 'Na gut, da war ich wohl etwas zu selbstsicher ...',
    ['Alivia', 'LADY', 'introSpeech', 'Tee hee, Paige just told me the most droll joke!'] => 'Hihi, Paige hat mir gerade den drolligsten Witz erzählt!',
    ['Alivia', 'LADY', 'winSpeech', 'You were an even more droll joke!'] => 'Du warst ein noch drolligerer Witz!',
    ['Alivia', 'LADY', 'loseSpeech', 'Hee hee... I was distracted, but it really was so funny, darling!'] => 'Hee hee ... Ich war abgelenkt, aber der war wirklich so lustig, Liebling!',
    ['Paige', 'LADY', 'introSpeech', 'We\'ve only a short battle together, so let\'s make the most of it!'] => 'Wir haben nur kurz Zeit für diesen Kampf, also machen wir das Beste draus!',
    ['Paige', 'LADY', 'winSpeech', 'Someone\'s got to lose, but I do hope you enjoyed yourself!'] => 'Einer muss verlieren, aber ich hoffe, du hattest Spaß!',
    ['Paige', 'LADY', 'loseSpeech', 'That was lovely! Oh, I must tell Livi about this!'] => 'Das war wundervoll! Oh, das muss ich Livi erzählen!',
    ['Anya', 'BEAUTY', 'introSpeech', 'Watch me as I battle, please. I\'m trying to become more graceful.'] => 'Sieh mir bitte beim Kämpfen zu. Ich möchte anmutiger werden.',
    ['Anya', 'BEAUTY', 'winSpeech', 'That was my best battle yet! Thank you, stranger!'] => 'Das war mein bester Kampf bisher! Danke, Fremder!',
    ['Anya', 'BEAUTY', 'loseSpeech', 'I guess I gotta learn to lose with grace, as well...'] => 'Ich muss wohl auch lernen, mit Anmut zu verlieren ...',
    ['Dawn', 'BEAUTY', 'introSpeech', 'Yawn... The lighting here makes me sleepy!'] => 'Gähn ... Die Beleuchtung hier macht mich schläfrig!',
    ['Dawn', 'BEAUTY', 'winSpeech', 'You did your best!'] => 'Du hast dein Bestes gegeben!',
    ['Dawn', 'BEAUTY', 'loseSpeech', 'Time for a nap...'] => 'Zeit für ein Nickerchen ...',
    ['Abby', 'NatureGirl', 'introSpeech', 'I\'m a bit hungry... You have any Water Stones? '] => 'Ich hab ein bisschen Hunger ... Hast du irgendwelche Wassersteine?',
    ['Abby', 'NatureGirl', 'winSpeech', 'Maybe I can buy one here...'] => 'Vielleicht kann ich hier einen kaufen ...',
    ['Abby', 'NatureGirl', 'loseSpeech', 'No? All right, I\'ll just get a sandwich instead...'] => 'Nein? Na gut, dann hol ich mir eben ein Sandwich ...',
    ['Gretel', 'NatureGirl', 'introSpeech', 'I\'m warnin\' ya, people hate to battle me!'] => 'Ich warn dich, keiner kämpft gern gegen mich!',
    ['Gretel', 'NatureGirl', 'winSpeech', 'Haha! Nothin\' like a loss to Gretel to make yer day! '] => 'Haha! Nichts versüßt den Tag so wie eine Niederlage gegen Gretel!',
    ['Gretel', 'NatureGirl', 'loseSpeech', 'What? How could I lose? Ya must\'ve cheated, I\'m sure of it!'] => 'Was? Wie konnte ich verlieren? Du musst geschummelt haben, ganz sicher!',
    ['Thomas', 'HIKER', 'introSpeech', 'Let me show you what the wilds have taught me.'] => 'Ich zeig dir, was ich in der Wildnis gelernt habe.',
    ['Thomas', 'HIKER', 'winSpeech', 'You should learn from the wilds!'] => 'Von der Wildnis kannst du noch was lernen!',
    ['Thomas', 'HIKER', 'loseSpeech', 'It seems I wasn\'t ready.'] => 'Sieht so aus, als wäre ich noch nicht bereit gewesen.',
    ['Zaki', 'HIKER', 'introSpeech', 'Just try me! I\'ve been hardened by nature!'] => 'Nur zu! Die Natur hat mich abgehärtet!',
    ['Zaki', 'HIKER', 'winSpeech', 'Smell ya later'] => 'Man riecht sich später!',
    ['Zaki', 'HIKER', 'loseSpeech', 'You\'re stronger than you look...'] => 'Du bist stärker, als du aussiehst ...',
    ['Naria', 'PSYCHIC_Female', 'introSpeech', 'You cannot fathom my superior intellect!'] => 'Du kannst dir meine überragende Intelligenz nicht mal vorstellen!',
    ['Naria', 'PSYCHIC_Female', 'winSpeech', 'Superiority reigns supreme! Wait, is that redundant?'] => 'Überlegenheit siegt immer! Moment, ist das nicht doppelt gemoppelt?',
    ['Naria', 'PSYCHIC_Female', 'loseSpeech', 'What could have been my downfall?'] => 'Was könnte mein Untergang gewesen sein?',
    ['Anabell', 'PSYCHIC_Female', 'introSpeech', 'Could this all be preordained?'] => 'War das alles vorherbestimmt?',
    ['Anabell', 'PSYCHIC_Female', 'winSpeech', 'Fate spoke, and you have listened well. '] => 'Das Schicksal sprach, und du hast gut zugehört.',
    ['Anabell', 'PSYCHIC_Female', 'loseSpeech', 'There is so much I don\'t know...'] => 'Es gibt so vieles, das ich nicht weiß ...',
    ['Andrew', 'Casanova', 'introSpeech', 'You\'ll be just another stepping stone on my path to victory!'] => 'Du bist nur ein weiterer Trittstein auf meinem Weg zum Sieg!',
    ['Andrew', 'Casanova', 'winSpeech', 'Stand down, stone.'] => 'Zurücktreten, Stein.',
    ['Andrew', 'Casanova', 'loseSpeech', 'I lost?! To you?'] => 'Ich hab verloren?! Gegen dich?',
    ['Liandra', 'BEAUTY', 'introSpeech', 'Try not to make this embarrassing... '] => 'Versuch, das nicht peinlich zu machen ...',
    ['Liandra', 'BEAUTY', 'winSpeech', 'What did I say before about being embarrassing?'] => 'Was hab ich vorhin über Peinlichkeit gesagt?',
    ['Liandra', 'BEAUTY', 'loseSpeech', 'Oh? This is quite unexpected...'] => 'Oh? Das ist ja ziemlich unerwartet ...',
    ['Eliah', 'GENTLEMAN', 'introSpeech', 'Let us have an entertaining battle.'] => 'Lass uns einen unterhaltsamen Kampf austragen.',
    ['Eliah', 'GENTLEMAN', 'winSpeech', 'Is that truly the best you can do? Balderdash!'] => 'War das wirklich alles, was du draufhast? Unsinn!',
    ['Eliah', 'GENTLEMAN', 'loseSpeech', 'Most excellent!'] => 'Ausgezeichnet!',
    ['Warner', 'GENTLEMAN', 'introSpeech', 'Show me what life has taught you, youngster.'] => 'Zeig mir, was dir das Leben beigebracht hat, junger Freund.',
    ['Warner', 'GENTLEMAN', 'winSpeech', 'If nothing else, age will school you yet.'] => 'Wenn sonst nichts hilft, wird dir das Alter schon noch etwas beibringen.',
