# Runtime hooks for the reviewed tables prepended by build_mod.py.
# Display-only: no save, cache, source-table, or disk writes.
  def self.key(text)
    return nil unless text.is_a?(String)
    Messages.stringToKey(text)
  end

  def self.german?
    MessageTypes.class_variable_get(:@@messages).instance_variable_get(:@reviewed_german_enabled)
  end

  def self.repair(table, source, value)
    pair = table && table[key(source)]
    # Preserve newer upstream translations instead of blindly overwriting them.
    pair && key(value) == key(pair[0]) ? pair[1] : value
  end

  module Lookup
    def loadMessageFile(filename)
      @reviewed_german_enabled = false
      result = super
      @reviewed_german_enabled = !!result && File.basename(filename.to_s.tr('\\', '/')).downcase == 'german.dat'
      result
    end

    def getFromHash(type, text)
      value = super
      return value unless @reviewed_german_enabled
      value = ReviewedGermanText.repair(ReviewedGermanText::TEXTS[type], text, value)
      if type == MessageTypes::ScriptTexts && ReviewedGermanText.key(value) == ReviewedGermanText.key(text)
        ReviewedGermanText::BOSS_TEXTS[ReviewedGermanText.key(text)] || value
      else
        value
      end
    end

    def getFromMapHash(map, text)
      value = super
      return value unless @reviewed_german_enabled
      value = ReviewedGermanText.repair(ReviewedGermanText::MAPS[map], text, value)
      ReviewedGermanText.repair(ReviewedGermanText::MAPS[0], text, value)
    end
  end

  # Localize at access time so a language change never mutates cached trainer data.
  module FacilityTrainer
    [:introSpeech, :winSpeech, :loseSpeech].each do |field|
      define_method(field) do
        source = super()
        return source unless ReviewedGermanText.german?
        ReviewedGermanText::FACILITY_TEXTS[[name, tclass.to_s, field.to_s, source]] || source
      end
    end
  end

  module FacilityBoss
    def pbBattleChallengeBeginSpeech
      value = super
      value.is_a?(String) ? _INTL(value) : value
    end

    def pbMinibossDialogueOverwrite(battle)
      result = super
      battle.endspeech = _INTL(battle.endspeech) if battle.endspeech.is_a?(String)
      battle.endspeechwin = _INTL(battle.endspeechwin) if battle.endspeechwin.is_a?(String)
      result
    end
    private :pbBattleChallengeBeginSpeech, :pbMinibossDialogueOverwrite
  end
end

Messages.prepend(ReviewedGermanText::Lookup) unless Messages.ancestors.include?(ReviewedGermanText::Lookup)
if defined?(BTTrainerData)
  BTTrainerData.prepend(ReviewedGermanText::FacilityTrainer) unless BTTrainerData.ancestors.include?(ReviewedGermanText::FacilityTrainer)
end
if Object.private_method_defined?(:pbBattleChallengeBeginSpeech) && Object.private_method_defined?(:pbMinibossDialogueOverwrite)
  Object.prepend(ReviewedGermanText::FacilityBoss) unless Object.ancestors.include?(ReviewedGermanText::FacilityBoss)
end

